def _plain_search_context(value):
    pending = [value]
    while pending:
        item = pending.pop()
        if type(item) is dict:
            if any(type(k) is not str for k in item):
                return False
            pending.extend(item.values())
        elif type(item) is list:
            pending.extend(item)
        elif type(item) not in (str, int, float, bool, type(None)):
            return False
    return True
